:hasMonetaryAmount a owl:DatatypeProperty ;
    rdfs:domain :MoaSegment ;
    rdfs:range xsd:decimal ;
    rdfs:label "has monetary amount" ;
    rdfs:comment "A monetary amount with qualifier." .

:hasQuantity a owl:DatatypeProperty ;
    rdfs:domain :QtySegment ;
    rdfs:range xsd:decimal ;
    rdfs:label "has quantity" ;
    rdfs:comment "A quantity value with qualifier." .

:hasReference a owl:DatatypeProperty ;
    rdfs:domain :RffSegment ;
    rdfs:range xsd:string ;
    rdfs:label "has reference" ;
    rdfs:comment "A reference value with qualifier." .

:hasAllowanceCharge a owl:DatatypeProperty ;
    rdfs:domain :AlcSegment ;
    rdfs:range xsd:decimal ;
    rdfs:label "has allowance/charge" ;
    rdfs:comment "Allowance or charge amount with qualifier." .

:hasTaxDetail a owl:ObjectProperty ;
    rdfs:domain :TaxSegment ;
    rdfs:range :Tax ;
    rdfs:label "has tax detail" ;
    rdfs:comment "Links a TAX segment to a tax breakdown." ;
    owl:inverseOf :isTaxDetailOf .

:isTaxDetailOf a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :TaxSegment ;
    rdfs:label "is tax detail of" ;
    rdfs:comment "Links a tax breakdown to its TAX segment context (inverse of hasTaxDetail)." .

:hasCurrency a owl:DatatypeProperty ;
    rdfs:domain :CuxSegment ;
    rdfs:range xsd:string ;
    rdfs:label "has currency" ;
    rdfs:comment "Currency code with qualifier." .

:hasPriceDetail a owl:ObjectProperty ;
    rdfs:domain :PriSegment ;
    rdfs:range :Price ;
    rdfs:label "has price detail" ;
    rdfs:comment "Links a PRI segment to a price value." ;
    owl:inverseOf :isPriceDetailOf .

:isPriceDetailOf a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :PriSegment ;
    rdfs:label "is price detail of" ;
    rdfs:comment "Links a price to its PRI segment context (inverse of hasPriceDetail)." .

:hasLineIdentifier a owl:DatatypeProperty ;
    rdfs:domain :LinSegment ;
    rdfs:range xsd:string ;
