    rdfs:range :InvoiceMessage ;
    rdfs:label "has assigned invoice" ;
    rdfs:comment "Links a business process to its assigned invoice message (inverse of assignedToBusinessProcess)." .

#################################################################
# Disjointness and Union
#################################################################

:InvoiceHeaderGroup owl:disjointWith :InvoiceLineItemGroup, :InvoiceSummaryGroup .
:InvoiceLineItemGroup owl:disjointWith :InvoiceSummaryGroup .
:InvoiceHeader owl:disjointWith :InvoiceDetail, :InvoiceSummary .
:InvoiceDetail owl:disjointWith :InvoiceSummary .
:Organization owl:disjointWith :Item, :AgentRole .
:Address owl:disjointWith :Item .
:InvoiceHeaderGroup owl:disjointUnionOf ( :InvoiceHeaderGroup :InvoiceLineItemGroup :InvoiceSummaryGroup ) .

#################################################################
# General Class Axioms and Restrictions
#################################################################

:InvoiceMessage owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
        [ a owl:Restriction ; owl:onProperty :hasHeaderGroup ; owl:someValuesFrom :InvoiceHeaderGroup ]
        [ a owl:Restriction ; owl:onProperty :hasLineItemGroup ; owl:someValuesFrom :InvoiceLineItemGroup ]
        [ a owl:Restriction ; owl:onProperty :hasSummaryGroup ; owl:someValuesFrom :InvoiceSummaryGroup ]
    )
] .

:OrganizationRoleAssignment owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
        [ a owl:Restriction ; owl:onProperty :hasAgentRole ; owl:someValuesFrom :AgentRole ]
        [ a owl:Restriction ; owl:onProperty :assignedOrganization ; owl:someValuesFrom :Organization ]
    )
] .

# Connecting ValidationRule to SHACLConstraint
:SHACLConstraint rdfs:subClassOf :ValidationRule .
"}

args.owl_content:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#edifact-invoic-ontology>
    a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Ontology" ;
    rdfs:comment "A deeply structured ontology for the UN/EDIFACT D96A INVOIC message, supporting EANCOM, EN 16931-1, and P2P-O alignment." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "Envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An INVOIC message representing a business invoice transaction." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A generic EDIFACT segment." .

:BgmSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." .

:NadSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." .

:DtmSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "DTM Segment" ;
    rdfs:comment "Date/Time/Period segment with qualifiers." .

:MoaSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "MOA Segment" ;
    rdfs:comment "Monetary Amount segment with qualifiers." .

:QtySegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "QTY Segment" ;
    rdfs:comment "Quantity segment with context." .

:RffSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "RFF Segment" ;
    rdfs:comment "Reference segment with qualifiers." .

:AlcSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "ALC Segment" ;
    rdfs:comment "Allowance/Charge segment." .

:TaxSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "TAX Segment" ;
    rdfs:comment "Tax detail segment with qualifiers and tax breakdown." .

:UnhSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "UNH Segment" ;
    rdfs:comment "Message Header segment." .

:UntSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "UNT Segment" ;
    rdfs:comment "Message Trailer segment." .

:CuxSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "CUX Segment" ;
    rdfs:comment "Currencies segment." .

:PriSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "PRI Segment" ;
    rdfs:comment "Price details segment." .

:LinSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "LIN Segment" ;
    rdfs:comment "Line item identification segment." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite." .

:InvoiceHeaderGroup a owl:Class ;
    rdfs:label "Invoice Header Group" ;
    rdfs:comment "Header group of the invoice message, containing header segments." .

:InvoiceLineItemGroup a owl:Class ;
    rdfs:label "Invoice Line Item Group" ;
    rdfs:comment "Line item group of the invoice message, containing line item segments." .

:InvoiceSummaryGroup a owl:Class ;
    rdfs:label "Invoice Summary Group" ;
    rdfs:comment "Summary group of the invoice message, containing summary segments." .

:InvoiceHeader a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Invoice Header" ;
    rdfs:comment "Header information for an invoice." .

:InvoiceDetail a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Invoice Detail" ;
    rdfs:comment "Detail information for an invoice, including line items." .

:InvoiceSummary a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Invoice Summary" ;
    rdfs:comment "Summary information for an invoice." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A single line item in the invoice detail section." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business organization involved in the invoice." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A specific role played by an organization (e.g., Buyer, Supplier, Delivery Party)." .

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Pivot class for reifying the assignment of a role to an organization within a specific invoice context." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "An identifier for an organization or item." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A unique global location identifier (GLN)." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service being invoiced." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value for an item or service." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax value or breakdown." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A process to which the invoice can be assigned (e.g., Purchase-to-Pay)." .

:ValidationRule a owl:Class ;
    rdfs:label "Validation Rule" ;
    rdfs:comment "A rule for validating the invoice structure or content. Referenced by SHACLConstraint." .

:SHACLConstraint a owl:Class ;
    rdfs:label "SHACL Constraint" ;
    rdfs:comment "A SHACL constraint for automated validation. Subclass of ValidationRule." ;
    rdfs:seeAlso :ValidationRule .

#################################################################
# Object and Data Properties
#################################################################

:hasMessage a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "has message" ;
    rdfs:comment "Links an interchange envelope to its contained message." ;
    owl:inverseOf :isMessageOf .

:isMessageOf a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "is message of" ;
    rdfs:comment "Links a message to its envelope (inverse of hasMessage)." .

:hasHeaderGroup a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceHeaderGroup ;
    rdfs:label "has header group" ;
    rdfs:comment "Links an invoice message to its header group." ;
    owl:inverseOf :isHeaderGroupOf .

:isHeaderGroupOf a owl:ObjectProperty ;
    rdfs:domain :InvoiceHeaderGroup ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is header group of" ;
    rdfs:comment "Links a header group to its invoice message (inverse of hasHeaderGroup)." .

:hasLineItemGroup a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceLineItemGroup ;
    rdfs:label "has line item group" ;
    rdfs:comment "Links an invoice message to its line item group." ;
    owl:inverseOf :isLineItemGroupOf .

:isLineItemGroupOf a owl:ObjectProperty ;
    rdfs:domain :InvoiceLineItemGroup ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is line item group of" ;
    rdfs:comment "Links a line item group to its invoice message (inverse of hasLineItemGroup)." .

:hasSummaryGroup a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceSummaryGroup ;
    rdfs:label "has summary group" ;
    rdfs:comment "Links an invoice message to its summary group." ;
    owl:inverseOf :isSummaryGroupOf .

:isSummaryGroupOf a owl:ObjectProperty ;
    rdfs:domain :InvoiceSummaryGroup ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is summary group of" ;
    rdfs:comment "Links a summary group to its invoice message (inverse of hasSummaryGroup)." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a message to its segments." ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "is segment of" ;
    rdfs:comment "Links a segment to its parent message (inverse of hasSegment)." .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a segment to its composite data elements." ;
    owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    rdfs:label "is composite element of" ;
    rdfs:comment "Links a composite element to its segment (inverse of hasCompositeElement)." .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a composite data element to its simple elements." ;
    owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "is simple element of" ;
    rdfs:comment "Links a simple element to its composite data element (inverse of hasSimpleElement)." .

:hasHeader a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :InvoiceHeaderGroup ;
    rdfs:range :InvoiceHeader ;
    rdfs:label "has header" ;
    rdfs:comment "Links an invoice header group to its header details." ;
    owl:inverseOf :isHeaderOf .

:isHeaderOf a owl:ObjectProperty ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :InvoiceHeaderGroup ;
    rdfs:label "is header of" ;
    rdfs:comment "Links header details to their header group (inverse of hasHeader)." .

:hasDetail a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :InvoiceLineItemGroup ;
    rdfs:range :InvoiceDetail ;
    rdfs:label "has detail" ;
    rdfs:comment "Links a line item group to its detail section." ;
    owl:inverseOf :isDetailOf .

:isDetailOf a owl:ObjectProperty ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :InvoiceLineItemGroup ;
    rdfs:label "is detail of" ;
    rdfs:comment "Links detail section to its line item group (inverse of hasDetail)." .

:hasSummary a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :InvoiceSummaryGroup ;
    rdfs:range :InvoiceSummary ;
    rdfs:label "has summary" ;
    rdfs:comment "Links a summary group to its summary section." ;
    owl:inverseOf :isSummaryOf .

:isSummaryOf a owl:ObjectProperty ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :InvoiceSummaryGroup ;
    rdfs:label "is summary of" ;
    rdfs:comment "Links summary section to its summary group (inverse of hasSummary)." .

:hasLineItem a owl:ObjectProperty ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :LineItem ;
    rdfs:label "has line item" ;
    rdfs:comment "Links an invoice detail section to its line items." ;
    owl:inverseOf :isLineItemOf .

:isLineItemOf a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :InvoiceDetail ;
    rdfs:label "is line item of" ;
    rdfs:comment "Links a line item to its invoice detail section (inverse of hasLineItem)." .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "Links an invoice message to organizations involved." ;
    owl:inverseOf :isOrganizationInvolvedIn .

:isOrganizationInvolvedIn a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is organization involved in" ;
    rdfs:comment "Links an organization to its invoice message context (inverse of involvesOrganization)." .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Links an invoice message to its organization-role assignments." ;
    owl:inverseOf :isRoleAssignmentOf .

:isRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is role assignment of" ;
    rdfs:comment "Links a role assignment to its invoice message context (inverse of hasRoleAssignment)." .

:hasAgentRole a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "has agent role" ;
    rdfs:comment "Links a role assignment to the agent role (e.g., Buyer, Supplier)." ;
    owl:inverseOf :isAgentRoleOf .

:isAgentRoleOf a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "is agent role of" ;
    rdfs:comment "Links an agent role to its role assignment context (inverse of hasAgentRole)." .

:assignedOrganization a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "assigned organization" ;
    rdfs:comment "Links a role assignment to the assigned organization." ;
    owl:inverseOf :isOrganizationAssignedTo .

:isOrganizationAssignedTo a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "is organization assigned to" ;
    rdfs:comment "Links an organization to its role assignment context (inverse of assignedOrganization)." .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its address." ;
    owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is address of" ;
    rdfs:comment "Links an address to its organization (inverse of hasAddress)." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an organization to its identifier(s)." ;
    owl:inverseOf :isIdentifierOf .

:isIdentifierOf a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    rdfs:label "is identifier of" ;
    rdfs:comment "Links an identifier to its organization context (inverse of hasIdentifier)." .

:hasGLN a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :GlobalLocationNumber ;
    rdfs:label "has GLN" ;
    rdfs:comment "Links an identifier to a Global Location Number." ;
    owl:inverseOf :isGLNOf .

:isGLNOf a owl:ObjectProperty ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range :Identifier ;
    rdfs:label "is GLN of" ;
    rdfs:comment "Links a GLN to its identifier context (inverse of hasGLN)." .

:hasItem a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    rdfs:label "has item" ;
    rdfs:comment "Links a line item to the invoiced item." ;
    owl:inverseOf :isItemOf .

:isItemOf a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    rdfs:label "is item of" ;
    rdfs:comment "Links an item to its line item context (inverse of hasItem)." .

:hasPrice a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    rdfs:label "has price" ;
    rdfs:comment "Links a line item to its price." ;
    owl:inverseOf :isPriceOf .

:isPriceOf a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    rdfs:label "is price of" ;
    rdfs:comment "Links a price to its line item context (inverse of hasPrice)." .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Links a summary to its tax details." ;
    owl:inverseOf :isTaxOf .

:isTaxOf a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :InvoiceSummary ;
    rdfs:label "is tax of" ;
    rdfs:comment "Links a tax to its invoice summary context (inverse of hasTax)." .

:hasInvoiceAmount a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range xsd:decimal ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "The total invoice amount." .

:hasInvoiceNumber a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number." .

:hasDate a owl:DatatypeProperty ;
    rdfs:domain :DtmSegment ;
    rdfs:range xsd:string ;
    rdfs:label "has date" ;
    rdfs:comment "A date value with qualifier." .

:hasMonetaryAmount a owl:DatatypeProperty ;
    rdfs:domain :MoaSegment ;
    rdfs:range xsd:decimal ;
    rdfs:label "has monetary amount" ;
    rdfs:comment "A monetary amount with qualifier." .

:hasQuantity a owl:DatatypeProperty ;
    rdfs:domain :QtySegment ;
    rdfs:range xsd:decimal ;
    rdfs:label "has quantity" ;
    rdfs:comment "A quantity value with qualifier." .

:hasReference a owl:DatatypeProperty ;
    rdfs:domain :RffSegment ;
    rdfs:range xsd:string ;
    rdfs:label "has reference" ;
    rdfs:comment "A reference value with qualifier." .

:hasAllowanceCharge a owl:DatatypeProperty ;
    rdfs:domain :AlcSegment ;
    rdfs:range xsd:decimal ;
    rdfs:label "has allowance/charge" ;
    rdfs:comment "Allowance or charge amount with qualifier." .

:hasTaxDetail a owl:ObjectProperty ;
    rdfs:domain :TaxSegment ;
    rdfs:range :Tax ;
    rdfs:label "has tax detail" ;
    rdfs:comment "Links a TAX segment to a tax breakdown." ;
    owl:inverseOf :isTaxDetailOf .

:isTaxDetailOf a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :TaxSegment ;
    rdfs:label "is tax detail of" ;
    rdfs:comment "Links a tax breakdown to its TAX segment context (inverse of hasTaxDetail)." .

:hasCurrency a owl:DatatypeProperty ;
    rdfs:domain :CuxSegment ;
    rdfs:range xsd:string ;
    rdfs:label "has currency" ;
    rdfs:comment "Currency code with qualifier." .

:hasPriceDetail a owl:ObjectProperty ;
    rdfs:domain :PriSegment ;
    rdfs:range :Price ;
    rdfs:label "has price detail" ;
    rdfs:comment "Links a PRI segment to a price value." ;
    owl:inverseOf :isPriceDetailOf .

:isPriceDetailOf a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :PriSegment ;
    rdfs:label "is price detail of" ;
    rdfs:comment "Links a price to its PRI segment context (inverse of hasPriceDetail)." .

:hasLineIdentifier a owl:DatatypeProperty ;
    rdfs:domain :LinSegment ;
    rdfs:range xsd:string ;
    rdfs:label "has line identifier" ;
    rdfs:comment "Line item identification value." .

:validatesWith a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :SHACLConstraint ;
    rdfs:label "validates with" ;
    rdfs:comment "Links an invoice message to its SHACL validation constraints." ;
    owl:inverseOf :isValidationFor .

:isValidationFor a owl:ObjectProperty ;
    rdfs:domain :SHACLConstraint ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is validation for" ;
    rdfs:comment "Links a SHACL constraint to its invoice message context (inverse of validatesWith)." ;
    rdfs:seeAlso :ValidationRule .

:assignedToBusinessProcess a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "assigned to business process" ;
    rdfs:comment "Links an invoice message to the business process it belongs to." ;
    owl:inverseOf :hasAssignedInvoice .

:hasAssignedInvoice a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "has assigned invoice" ;
    rdfs:comment "Links a business process to its assigned invoice message (inverse of assignedToBusinessProcess)." .

#################################################################
# Disjointness and Union
#################################################################

:InvoiceHeaderGroup owl:disjointWith :InvoiceLineItemGroup, :InvoiceSummaryGroup .
:InvoiceLineItemGroup owl:disjointWith :InvoiceSummaryGroup .
:InvoiceHeader owl:disjointWith :InvoiceDetail, :InvoiceSummary .
:InvoiceDetail owl:disjointWith :InvoiceSummary .
:Organization owl:disjointWith :Item, :AgentRole .
:Address owl:disjointWith :Item .
:InvoiceHeaderGroup owl:disjointUnionOf ( :InvoiceHeaderGroup :InvoiceLineItemGroup :InvoiceSummaryGroup ) .

#################################################################
# General Class Axioms and Restrictions
#################################################################

:InvoiceMessage owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
        [ a owl:Restriction ; owl:onProperty :hasHeaderGroup ; owl:someValuesFrom :InvoiceHeaderGroup ]
        [ a owl:Restriction ; owl:onProperty :hasLineItemGroup ; owl:someValuesFrom :InvoiceLineItemGroup ]
        [ a owl:Restriction ; owl:onProperty :hasSummaryGroup ; owl:someValuesFrom :InvoiceSummaryGroup ]
    )
] .

:OrganizationRoleAssignment owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
        [ a owl:Restriction ; owl:onProperty :hasAgentRole ; owl:someValuesFrom :AgentRole ]
        [ a owl:Restriction ; owl:onProperty :assignedOrganization ; owl:someValuesFrom :Organization ]
    )
] .

# Connecting ValidationRule to SHACLConstraint
:SHACLConstraint rdfs:subClassOf :ValidationRule .

