    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "assigned to business process" ;
    rdfs:comment "Links an invoice message to the business process it belongs to." .

#################################################################
# Disjointness and Union
#################################################################

:InvoiceHeaderGroup owl:disjointWith :InvoiceLineItemGroup, :InvoiceSummaryGroup .
:InvoiceLineItemGroup owl:disjointWith :InvoiceSummaryGroup .
:InvoiceHeader owl:disjointWith :InvoiceDetail, :InvoiceSummary .
:InvoiceDetail owl:disjointWith :InvoiceSummary .
:Organization owl:disjointWith :Item, :AgentRole .
:Address owl:disjointWith :Item .
:InvoiceHeaderGroup owl:disjointUnionOf ( :InvoiceHeaderGroup :InvoiceLineItemGroup :InvoiceSummaryGroup ) .

#################################################################
# General Class Axioms and Restrictions
#################################################################

:InvoiceMessage owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
        [ a owl:Restriction ; owl:onProperty :hasHeaderGroup ; owl:someValuesFrom :InvoiceHeaderGroup ]
        [ a owl:Restriction ; owl:onProperty :hasLineItemGroup ; owl:someValuesFrom :InvoiceLineItemGroup ]
        [ a owl:Restriction ; owl:onProperty :hasSummaryGroup ; owl:someValuesFrom :InvoiceSummaryGroup ]
    )
] .

:OrganizationRoleAssignment owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
        [ a owl:Restriction ; owl:onProperty :hasAgentRole ; owl:someValuesFrom :AgentRole ]
        [ a owl:Restriction ; owl:onProperty :assignedOrganization ; owl:someValuesFrom :Organization ]
    )
] .

