:hasValidationRule a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationRule ;
    rdfs:label "has validation rule" ;
    rdfs:comment "Links an invoice message or SHACL constraint to its validation rule." ;
    owl:inverseOf :isValidationRuleFor .

:isValidationRuleFor a owl:ObjectProperty ;
    rdfs:domain :ValidationRule ;
    rdfs:range :InvoiceMessage ;
