    rdfs:comment "Envelope that contains EDIFACT messages, including INVOIC." .

:Message rdf:type owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "Generic EDIFACT message structure." .

:InvoiceMessage rdf:type owl:Class ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "INVOIC message for global trade transactions." ;
    rdfs:subClassOf :Message .

:Segment rdf:type owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGMSegment rdf:type owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." ;
    rdfs:subClassOf :Segment .

:NADSegment rdf:type owl:Class ;
