    rdfs:comment "Links Segment to composite data elements." ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement .
:compositeElementOf rdf:type owl:ObjectProperty ;
    rdfs:label "composite element of" ;
    rdfs:comment "Inverse of hasCompositeElement." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    owl:inverseOf :hasCompositeElement .

:hasSimpleElement rdf:type owl:ObjectProperty ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links CompositeDataElement to simple data elements." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement .
:simpleElementOf rdf:type owl:ObjectProperty ;
    rdfs:label "simple element of" ;
    rdfs:comment "Inverse of hasSimpleElement." ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    owl:inverseOf :hasSimpleElement .

:playsRole rdf:type owl:ObjectProperty ;
    rdfs:label "plays role" ;
    rdfs:comment "Links Organization to RoleAssignment pivot class." ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment .
:rolePlayedBy rdf:type owl:ObjectProperty ;
    rdfs:label "role played by" ;
    rdfs:comment "Inverse of playsRole." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    owl:inverseOf :playsRole .

:hasAgentRole rdf:type owl:ObjectProperty ;
    rdfs:label "has agent role" ;
    rdfs:comment "Links RoleAssignment to AgentRole." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole .
:hasAgentRole rdf:type owl:FunctionalProperty .
:agentRoleOf rdf:type owl:ObjectProperty ;
    rdfs:label "agent role of" ;
    rdfs:comment "Inverse of hasAgentRole." ;
    rdfs:domain :AgentRole ;
    rdfs:range :RoleAssignment ;
    owl:inverseOf :hasAgentRole .

:involvesOrganization rdf:type owl:ObjectProperty ;
    rdfs:label "involves organization" ;
    rdfs:comment "Links InvoiceMessage to involved organizations." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization .
:involvedInInvoice rdf:type owl:ObjectProperty ;
    rdfs:label "involved in invoice" ;
    rdfs:comment "Inverse of involvesOrganization." ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :involvesOrganization .

:hasAddress rdf:type owl:ObjectProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Links Organization to Address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address .
:addressOf rdf:type owl:ObjectProperty ;
    rdfs:label "address of" ;
    rdfs:comment "Inverse of hasAddress." ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    owl:inverseOf :hasAddress .

:hasIdentifier rdf:type owl:ObjectProperty ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links Organization to generic identifiers." ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier .
:identifierOf rdf:type owl:ObjectProperty ;
    rdfs:label "identifier of" ;
    rdfs:comment "Inverse of hasIdentifier." ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    owl:inverseOf :hasIdentifier .

:hasGLN rdf:type owl:ObjectProperty ;
    rdfs:label "has GLN" ;
    rdfs:comment "Links Organization to its GLN identifier." ;
    rdfs:domain :Organization ;
    rdfs:range :GLNIdentifier .
:hasGLN rdf:type owl:FunctionalProperty, owl:InverseFunctionalProperty .
:glnOf rdf:type owl:ObjectProperty ;
    rdfs:label "GLN of" ;
    rdfs:comment "Inverse of hasGLN." ;
    rdfs:domain :GLNIdentifier ;
    rdfs:range :Organization ;
    owl:inverseOf :hasGLN .

:hasLineItem rdf:type owl:ObjectProperty ;
    rdfs:label "has line item" ;
    rdfs:comment "Links DetailSection to individual line items." ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem .
:lineItemOf rdf:type owl:ObjectProperty ;
    rdfs:label "line item of" ;
    rdfs:comment "Inverse of hasLineItem." ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    owl:inverseOf :hasLineItem .

:describesItem rdf:type owl:ObjectProperty ;
    rdfs:label "describes item" ;
    rdfs:comment "Links LineItem to Item." ;
    rdfs:domain :LineItem ;
    rdfs:range :Item .
:itemDescribedBy rdf:type owl:ObjectProperty ;
    rdfs:label "item described by" ;
    rdfs:comment "Inverse of describesItem." ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    owl:inverseOf :describesItem .

:hasNetPrice rdf:type owl:ObjectProperty ;
    rdfs:label "has net price" ;
    rdfs:comment "Links LineItem to price." ;
    rdfs:domain :LineItem ;
    rdfs:range :Price .
:hasNetPrice rdf:type owl:FunctionalProperty .
:netPriceOf rdf:type owl:ObjectProperty ;
    rdfs:label "net price of" ;
    rdfs:comment "Inverse of hasNetPrice." ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    owl:inverseOf :hasNetPrice .

:hasInvoiceAmount rdf:type owl:ObjectProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Links SummarySection to invoice amount." ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceAmount .
:hasInvoiceAmount rdf:type owl:FunctionalProperty .
:invoiceAmountOf rdf:type owl:ObjectProperty ;
    rdfs:label "invoice amount of" ;
    rdfs:comment "Inverse of hasInvoiceAmount." ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range :SummarySection ;
    owl:inverseOf :hasInvoiceAmount .

:hasInvoiceNumber rdf:type owl:ObjectProperty ;
    rdfs:label "has invoice number" ;
    rdfs:comment "Links HeaderSection to invoice number." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :InvoiceNumber .
:hasInvoiceNumber rdf:type owl:FunctionalProperty .
:invoiceNumberOf rdf:type owl:ObjectProperty ;
    rdfs:label "invoice number of" ;
    rdfs:comment "Inverse of hasInvoiceNumber." ;
    rdfs:domain :InvoiceNumber ;
    rdfs:range :HeaderSection ;
    owl:inverseOf :hasInvoiceNumber .

:hasBusinessProcess rdf:type owl:ObjectProperty ;
    rdfs:label "has business process" ;
    rdfs:comment "Links InvoiceMessage to business process." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess .
:businessProcessOf rdf:type owl:ObjectProperty ;
    rdfs:label "business process of" ;
    rdfs:comment "Inverse of hasBusinessProcess." ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasBusinessProcess .

:hasDate rdf:type owl:DatatypeProperty ;
    rdfs:label "has date" ;
    rdfs:comment "Date associated with header section." ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string .

:hasReferenceNumber rdf:type owl:DatatypeProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "Reference number in header section." ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string .

:hasTaxAmount rdf:type owl:DatatypeProperty ;
    rdfs:label "has tax amount" ;
    rdfs:comment "Tax amount in summary section." ;
    rdfs:domain :SummarySection ;
    rdfs:range xsd:decimal .
:hasTaxAmount rdf:type owl:FunctionalProperty .

:hasMandatoryIdentifier rdf:type owl:DatatypeProperty ;
    rdfs:label "has mandatory identifier" ;
    rdfs:comment "Mandatory identifier required by D96A directory." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range xsd:string .

#################################################################
# Complex Axioms & Restrictions
#################################################################
:BuyerRole rdf:type :AgentRole ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "Role identifying the buyer organization in the invoice." .

:DeliveryPartyRole rdf:type :AgentRole ;
    rdfs:label "Delivery Party Role" ;
    rdfs:comment "Role identifying the delivery party organization in the invoice." .

:RoleAssignment owl:equivalentClass [
    rdf:type owl:Restriction ;
    owl:onProperty :hasAgentRole ;
    owl:allValuesFrom :AgentRole
] .

:Organization owl:equivalentClass [
    rdf:type owl:Restriction ;
    owl:onProperty :hasGLN ;
    owl:allValuesFrom :GLNIdentifier
] .

:LineItem owl:equivalentClass [
    rdf:type owl:Restriction ;
    owl:onProperty :hasNetPrice ;
    owl:allValuesFrom :Price
] .

#################################################################
# Annotations
#################################################################
# (Each class and property has rdfs:label and rdfs:comment)
"}

