@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

:EDIFACT_INVOIC_Ontology rdf:type owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Ontology" ;
    rdfs:comment "Ontology for representing UN/EDIFACT INVOIC messages, segments, and business roles, aligned with EN 16931-1 and P2P-O standards." .

#################################################################
# Classes
#################################################################
:InterchangeEnvelope rdf:type owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "Envelope that contains EDIFACT messages, including INVOIC." .

:Message rdf:type owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "Generic EDIFACT message structure." .

:InvoiceMessage rdf:type owl:Class ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "INVOIC message for global trade transactions." ;
    rdfs:subClassOf :Message .

:Segment rdf:type owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGM_Segment rdf:type owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." ;
    rdfs:subClassOf :Segment .

:NAD_Segment rdf:type owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." ;
    rdfs:subClassOf :Segment .

:CompositeDataElement rdf:type owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "Composite element within a segment, containing simple elements." .

:SimpleDataElement rdf:type owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "Atomic data element within a composite." .

:HeaderSection rdf:type owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "Section containing document dates and reference numbers." .

:DetailSection rdf:type owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "Section listing individual line items." .

:SummarySection rdf:type owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "Section providing total tax and invoice amounts." .

:Organization rdf:type owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "Entity involved in the invoice, may play multiple roles." .

:AgentRole rdf:type owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "Role played by an organization (e.g., Buyer, Delivery Party)." .

:Address rdf:type owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "Address associated with an organization." .

:Item rdf:type owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "Goods or services sold in the invoice." .

:Price rdf:type owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "Net price of items in the invoice." .

:InvoiceAmount rdf:type owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "Total amount of the invoice." .

:InvoiceNumber rdf:type owl:Class ;
    rdfs:label "Invoice Number" ;
    rdfs:comment "Unique identifier for the invoice." .

:BusinessProcess rdf:type owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "Process to which the invoice is assigned (e.g., procurement)." .

:Identifier rdf:type owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "Generic identifier for organizations or items." .

:GLN_Identifier rdf:type owl:Class ;
    rdfs:label "Global Location Number Identifier" ;
    rdfs:comment "Global Location Number assigned to organizations." ;
    rdfs:subClassOf :Identifier .

:RoleAssignment rdf:type owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "Reification class linking organizations to agent roles and addresses." .

:LineItem rdf:type owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "Individual item entry in the invoice detail section." .

#################################################################
# Disjointness and DisjointUnion
#################################################################
:HeaderSection owl:disjointWith :DetailSection, :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Item .
:InvoiceAmount owl:disjointWith :InvoiceNumber .

#################################################################
# Properties
#################################################################
:containsMessage rdf:type owl:ObjectProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Links InterchangeEnvelope to contained Message." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:FunctionalProperty .

:hasSegment rdf:type owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Links Message to its segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment .

:hasSection rdf:type owl:ObjectProperty ;
    rdfs:label "has section" ;
    rdfs:comment "Links InvoiceMessage to header, detail, and summary sections." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range _:SectionUnion .

_:SectionUnion rdf:type owl:Class ;
    owl:disjointUnionOf (:HeaderSection :DetailSection :SummarySection) .

:hasCompositeElement rdf:type owl:ObjectProperty ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links Segment to composite data elements." ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement .

:hasSimpleElement rdf:type owl:ObjectProperty ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links CompositeDataElement to simple data elements." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement .

:playsRole rdf:type owl:ObjectProperty ;
    rdfs:label "plays role" ;
    rdfs:comment "Links Organization to RoleAssignment pivot class." ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment .

:hasAgentRole rdf:type owl:ObjectProperty ;
    rdfs:label "has agent role" ;
    rdfs:comment "Links RoleAssignment to AgentRole." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    owl:FunctionalProperty .

:involvesOrganization rdf:type owl:ObjectProperty ;
    rdfs:label "involves organization" ;
    rdfs:comment "Links InvoiceMessage to involved organizations." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization .

:hasAddress rdf:type owl:ObjectProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Links Organization to Address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address .

:hasIdentifier rdf:type owl:ObjectProperty ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links Organization to generic identifiers." ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier .

:hasGLN rdf:type owl:ObjectProperty ;
    rdfs:label "has GLN" ;
    rdfs:comment "Links Organization to its GLN identifier." ;
    rdfs:domain :Organization ;
    rdfs:range :GLN_Identifier ;
    owl:FunctionalProperty, owl:InverseFunctionalProperty .

:hasLineItem rdf:type owl:ObjectProperty ;
    rdfs:label "has line item" ;
    rdfs:comment "Links DetailSection to individual line items." ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem .

:describesItem rdf:type owl:ObjectProperty ;
    rdfs:label "describes item" ;
    rdfs:comment "Links LineItem to Item." ;
    rdfs:domain :LineItem ;
    rdfs:range :Item .

:hasNetPrice rdf:type owl:ObjectProperty ;
    rdfs:label "has net price" ;
    rdfs:comment "Links LineItem to price." ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    owl:FunctionalProperty .

:hasInvoiceAmount rdf:type owl:ObjectProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Links SummarySection to invoice amount." ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceAmount ;
    owl:FunctionalProperty .

:hasInvoiceNumber rdf:type owl:ObjectProperty ;
    rdfs:label "has invoice number" ;
    rdfs:comment "Links HeaderSection to invoice number." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :InvoiceNumber ;
    owl:FunctionalProperty .

:hasBusinessProcess rdf:type owl:ObjectProperty ;
    rdfs:label "has business process" ;
    rdfs:comment "Links InvoiceMessage to business process." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess .

:hasDate rdf:type owl:DatatypeProperty ;
    rdfs:label "has date" ;
    rdfs:comment "Date associated with header section." ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string .

:hasReferenceNumber rdf:type owl:DatatypeProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "Reference number in header section." ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string .

:hasTaxAmount rdf:type owl:DatatypeProperty ;
    rdfs:label "has tax amount" ;
    rdfs:comment "Tax amount in summary section." ;
    rdfs:domain :SummarySection ;
    rdfs:range xsd:decimal ;
    owl:FunctionalProperty .

:hasMandatoryIdentifier rdf:type owl:DatatypeProperty ;
    rdfs:label "has mandatory identifier" ;
    rdfs:comment "Mandatory identifier required by D96A directory." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range xsd:string .

#################################################################
# Property Characteristics
#################################################################
# (Property characteristics already included above via owl:FunctionalProperty, owl:InverseFunctionalProperty)

