@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/storyid> a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Message Ontology" ;
    rdfs:comment "A deep and profoundly structured ontology for UN/EDIFACT INVOIC messages, roles, identifiers, and business process alignment." .

#################################################################
# Classes
#################################################################
:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "Envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message, container for segments." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An EDIFACT INVOIC message representing an invoice document." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment in an EDIFACT message (e.g., BGM, NAD)." .

:BGM_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." .

:NAD_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element grouping simple data elements." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element in a segment or composite." .

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "Header section of an invoice message, containing metadata and references." .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "Detail section listing individual line items." .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "Summary section providing totals, tax, and invoice amount." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A line item in the invoice, representing a sold item." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice (buyer, seller, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the transaction (e.g., Buyer, Seller, Delivery Party)." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "Pivot class associating an organization with a role in a specific context." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "An address associated with an organization (headquarters, warehouse, etc.)." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier for organizations, roles, or documents." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A global location identifier for organizations or addresses." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item sold in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "Price information for an item or invoice." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information for the invoice." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

#################################################################
# Disjoint Classes
#################################################################
:HeaderSection owl:disjointWith :DetailSection, :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Address, :Item .
:Item owl:disjointWith :Price, :Tax .

#################################################################
# Object Properties
#################################################################
:containsMessage a owl:ObjectProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an interchange envelope to its contained message." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Associates a message with its segments." .

:hasSection a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :HeaderSection, :DetailSection, :SummarySection ;
    rdfs:label "has section" ;
    rdfs:comment "Associates an invoice message with its sections." .

:hasLineItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    rdfs:label "has line item" ;
    rdfs:comment "Associates a detail section with its line items." .

:hasOrganization a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    rdfs:label "has organization" ;
    rdfs:comment "Links an invoice message to the involved organizations." .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Links an organization to its role assignments." .

:playsRole a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "plays role" ;
    rdfs:comment "Associates a role assignment with a specific agent role (e.g., Buyer, Seller)." .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its address." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an organization to its identifier(s)." .

:hasGlobalLocationNumber a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :GlobalLocationNumber ;
    rdfs:label "has Global Location Number" ;
    rdfs:comment "Links an identifier to a Global Location Number." .

:soldItem a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    rdfs:label "sold item" ;
    rdfs:comment "Links a line item to the item sold." .

:hasPrice a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    rdfs:label "has price" ;
    rdfs:comment "Associates a line item with its price." .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Links a summary section to tax information." .

:assignedToProcess a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "assigned to process" ;
    rdfs:comment "Assigns an invoice message to a business process." .

#################################################################
# Data Properties
#################################################################
:hasInvoiceNumber a owl:DatatypeProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number." .

:hasInvoiceDate a owl:DatatypeProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice date" ;
    rdfs:comment "The date of the invoice." .

:hasReferenceNumber a owl:DatatypeProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has reference number" ;
    rdfs:comment "A reference number in the header section." .

:hasNetPrice a owl:DatatypeProperty ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal ;
    rdfs:label "has net price" ;
    rdfs:comment "The net price of an item." .

:hasQuantity a owl:DatatypeProperty ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal ;
    rdfs:label "has quantity" ;
    rdfs:comment "The quantity of the item sold." .

:hasTotalAmount a owl:DatatypeProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range xsd:decimal ;
    rdfs:label "has total amount" ;
    rdfs:comment "The total invoice amount." .

:hasTaxAmount a owl:DatatypeProperty ;
    rdfs:domain :Tax ;
    rdfs:range xsd:decimal ;
    rdfs:label "has tax amount" ;
    rdfs:comment "The amount of tax in the summary section." .

:hasAddressLine a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "has address line" ;
    rdfs:comment "A line of address text." .

:hasOrganizationName a owl:DatatypeProperty ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    rdfs:label "has organization name" ;
    rdfs:comment "The name of the organization." .

:hasRoleCode a owl:DatatypeProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range xsd:string ;
    rdfs:label "has role code" ;
    rdfs:comment "The code representing the agent role (e.g., 'BY' for Buyer)." .

:hasIdentifierValue a owl:DatatypeProperty ;
    rdfs:domain :Identifier ;
    rdfs:range xsd:string ;
    rdfs:label "has identifier value" ;
    rdfs:comment "The value of an identifier (e.g., GLN, VAT number)." .

#################################################################
# Complex Axioms & Restrictions
#################################################################
:InvoiceMessage owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      :Message
      [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :HeaderSection ]
      [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :DetailSection ]
      [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :SummarySection ]
    )
] .

:RoleAssignment owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      [ a owl:Restriction ; owl:onProperty :playsRole ; owl:someValuesFrom :AgentRole ]
      [ a owl:Restriction ; owl:onProperty :hasAddress ; owl:allValuesFrom :Address ]
    )
] .

:LineItem owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      [ a owl:Restriction ; owl:onProperty :soldItem ; owl:someValuesFrom :Item ]
      [ a owl:Restriction ; owl:onProperty :hasPrice ; owl:someValuesFrom :Price ]
      [ a owl:Restriction ; owl:onProperty :hasQuantity ; owl:someValuesFrom xsd:decimal ]
    )
] .

#################################################################
# Annotations for Classes and Properties are included as rdfs:label and rdfs:comment above
#################################################################
"}

