:isLineItemOf a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    rdfs:label "is line item of" ;
    rdfs:comment "Inverse of hasLineItem." .

:hasOrganization a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    rdfs:label "has organization" ;
    rdfs:comment "Links an invoice message to the involved organizations." .
    owl:inverseOf :isOrganizationOf .

:isOrganizationOf a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is organization of" ;
    rdfs:comment "Inverse of hasOrganization." .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Links an organization to its role assignments." .
    owl:inverseOf :isRoleAssignmentOf .

:isRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "is role assignment of" ;
    rdfs:comment "Inverse of hasRoleAssignment." .

:playsRole a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "plays role" ;
    rdfs:comment "Associates a role assignment with a specific agent role (e.g., Buyer, Seller)." .
    owl:inverseOf :isRolePlayedBy .

:isRolePlayedBy a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :RoleAssignment ;
    rdfs:label "is role played by" ;
    rdfs:comment "Inverse of playsRole." .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its address." .
    owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is address of" ;
    rdfs:comment "Inverse of hasAddress." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an organization to its identifier(s)." .
    owl:inverseOf :isIdentifierOf .

:isIdentifierOf a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    rdfs:label "is identifier of" ;
    rdfs:comment "Inverse of hasIdentifier." .

:hasGlobalLocationNumber a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :GlobalLocationNumber ;
    rdfs:label "has Global Location Number" ;
    rdfs:comment "Links an identifier to a Global Location Number." .
    owl:inverseOf :isGlobalLocationNumberOf .

:isGlobalLocationNumberOf a owl:ObjectProperty ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range :Identifier ;
    rdfs:label "is Global Location Number of" ;
    rdfs:comment "Inverse of hasGlobalLocationNumber." .

:soldItem a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    rdfs:label "sold item" ;
    rdfs:comment "Links a line item to the item sold." .
    owl:inverseOf :isItemSoldIn .

:isItemSoldIn a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    rdfs:label "is item sold in" ;
    rdfs:comment "Inverse of soldItem." .

:hasPrice a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    rdfs:label "has price" ;
    rdfs:comment "Associates a line item with its price." .
    owl:inverseOf :isPriceOf .

:isPriceOf a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    rdfs:label "is price of" ;
    rdfs:comment "Inverse of hasPrice." .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Links a summary section to tax information." .
    owl:inverseOf :isTaxOf .

:isTaxOf a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :SummarySection ;
    rdfs:label "is tax of" ;
    rdfs:comment "Inverse of hasTax." .

:assignedToProcess a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "assigned to process" ;
    rdfs:comment "Assigns an invoice message to a business process." .
    owl:inverseOf :hasAssignedInvoice .

:hasAssignedInvoice a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "has assigned invoice" ;
    rdfs:comment "Inverse of assignedToProcess." .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Connects a segment to its composite data elements." .
    owl:inverseOf :isCompositeElementOf .
:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    rdfs:label "is composite element of" ;
    rdfs:comment "Inverse of hasCompositeElement." .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Connects a composite data element to its simple data elements." .
    owl:inverseOf :isSimpleElementOf .
:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "is simple element of" ;
    rdfs:comment "Inverse of hasSimpleElement." .

#################################################################
# Data Properties
#################################################################
:hasInvoiceNumber a owl:DatatypeProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number." .

:hasInvoiceDate a owl:DatatypeProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice date" ;
