#################################################################
# Complex Axioms & Restrictions
#################################################################
# Section as superclass for HeaderSection, DetailSection, SummarySection
:Section a owl:Class ;
    rdfs:label "Section" ;
    rdfs:comment "Superclass for HeaderSection, DetailSection, SummarySection." .
:HeaderSection rdfs:subClassOf :Section .
:DetailSection rdfs:subClassOf :Section .
:SummarySection rdfs:subClassOf :Section .

:InvoiceMessage owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      :Message
      [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :HeaderSection ]
      [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :DetailSection ]
      [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :SummarySection ]
    )
] .

:RoleAssignment owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      [ a owl:Restriction ; owl:onProperty :playsRole ; owl:someValuesFrom :AgentRole ]
      [ a owl:Restriction ; owl:onProperty :hasAddress ; owl:allValuesFrom :Address ]
    )
] .

:LineItem owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      [ a owl:Restriction ; owl:onProperty :soldItem ; owl:someValuesFrom :Item ]
      [ a owl:Restriction ; owl:onProperty :hasPrice ; owl:someValuesFrom :Price ]
      [ a owl:Restriction ; owl:onProperty :hasQuantity ; owl:someValuesFrom xsd:decimal ]
    )
] .

